package ar.com.miflix.admin

import com.google.gson.*
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.time.Instant

@RunWith(RobolectricTestRunner::class)
@Config(sdk=[28],manifest=Config.NONE)
@OptIn(ExperimentalCoroutinesApi::class)
class SagaDetectionTest {
    class Store:StateStore {var value:JsonObject?=null;var fail=false;override fun read()=value?.deepCopy();override fun write(state:JsonObject){check(!fail);value=state.deepCopy()}}
    private fun obj(s:String)=JsonParser.parseString(s).asJsonObject
    private fun cat(vararg ids:Int)=obj("""{"schema_version":1,"items":[]}""").apply {ids.forEachIndexed {i,n ->array("items").add(obj("""{"id":"p$i","tipo":"pelicula","titulo":"Película $i","tmdb_id":$n,"telegram_url":"https://t.me/synthetic/$i","fecha_agregado":"2024-01-01T00:00:00Z"}"""))}}
    private fun detail(id:Long=10)=obj("""{"id":$id,"name":"Saga $id","overview":"Descripción","poster_path":"/poster.jpg","backdrop_path":"/background.jpg","parts":[{"id":1,"title":"Uno"},{"id":2,"title":"Dos"},{"id":3,"title":"Tres"}]}""")
    private class Provider(val movie:(Long)->Long?={10},val collection:(Long)->JsonObject):SagaProvider {
        var calls=0;var details=0;var canceled=false
        override fun membership(movieId:Long):Long? {calls++;return movie(movieId)}
        override fun detail(collectionId:Long):JsonObject {details++;return collection(collectionId)}
        override fun cancel(){canceled=true}
    }
    private fun provider(movie:(Long)->Long?={10})=Provider(movie,{detail(it)})
    private fun engine(p:SagaProvider,s:Store=Store(),wait:suspend(Long)->Unit={})=SagaDetection(p,SagaCache(s),wait)
    @Test fun emptyCatalogDoesNoRequests()=runTest {val p=provider();var progress=SagaProgress();assertTrue(engine(p).scan(cat(),CollectionRules.empty()){s,_->progress=s}.isEmpty());assertEquals(0,p.calls);assertTrue(progress.complete)}
    @Test fun missingAndInvalidIdsNotGuessedByTitle()=runTest {val c=cat(1);c.array("items")[0].asJsonObject.remove("tmdb_id");val p=provider();var progress=SagaProgress();engine(p).scan(c,CollectionRules.empty()){s,_->progress=s};assertEquals(1,progress.missing);assertEquals(0,p.calls)}
    @Test fun integerIdsStrictAndBounded() {for(v in listOf("0","-1","1.2","1e2","2147483648","null","true","{}")) assertNull(SagaDetection.positiveId(obj("""{"tmdb_id":$v}"""),"tmdb_id"));assertEquals(4L,SagaDetection.positiveId(obj("""{"tmdb_id":"4"}"""),"tmdb_id"))}
    @Test fun seriesAnimeNotQueried()=runTest {val c=cat(1,2,3);c.array("items")[1].asJsonObject.addProperty("tipo","serie");c.array("items")[2].asJsonObject.addProperty("tipo","anime");val p=provider();engine(p).scan(c,CollectionRules.empty()){_,_->};assertEquals(1,p.calls)}
    @Test fun nullMembershipIsNotInvented()=runTest {val p=provider {null};assertTrue(engine(p).scan(cat(1),CollectionRules.empty()){_,_->}.isEmpty());assertEquals(0,p.details)}
    @Test fun groupSameSagaRequestsDetailOnce()=runTest {val p=provider();val rows=engine(p).scan(cat(1,2),CollectionRules.empty()){_,_->};assertEquals(1,rows.size);assertEquals(1,p.details);assertEquals(listOf("p0","p1"),rows.single().exact)}
    @Test fun differentSagasStayIndependent()=runTest {val p=provider {it*10};val rows=engine(p).scan(cat(1,2),CollectionRules.empty()){_,_->};assertEquals(listOf(10L,20L),rows.map {it.id})}
    @Test fun duplicateMovieIdsRequestedOnceAndExcludedAsAmbiguous()=runTest {val p=provider();val row=engine(p).scan(cat(1,1),CollectionRules.empty()){_,_->}.single();assertEquals(1,p.calls);assertEquals(1,row.ambiguous.size);assertTrue(row.exact.isEmpty());assertFalse(row.actionable)}
    @Test fun similarManualCollectionIsNotMerged() {val local=CollectionRules.fresh().apply{addProperty("nombre","Saga 10")};val root=CollectionRules.save(CollectionRules.empty(),local,null);val row=SagaDetection.proposal(detail(),cat(1),root);assertNull(row.current);val next=SagaDetection.approve(root,cat(1),listOf(row),setOf(10));assertEquals(2,CollectionRules.list(next).size)}
    @Test fun existingPredatorRecognizedByTmdbIdAndNeverDuplicated() {val d=CollectionRules.fresh().apply{addProperty("nombre","Mi Depredador");addProperty("origen","tmdb");addProperty("tmdb_collection_id",10)};val c=cat(1,2);val root=CollectionRules.save(CollectionRules.empty(),CollectionRules.members(d,listOf("p0")),null);val p=SagaDetection.proposal(detail(),c,root);assertNotNull(p.current);assertEquals(listOf("p1"),p.additions);val next=SagaDetection.approve(root,c,listOf(p),setOf(10));assertEquals(1,CollectionRules.list(next).size);assertEquals(d.text("id"),CollectionRules.list(next).single().text("id"));assertFalse(SagaDetection.proposal(detail(),c,next).actionable)}
    @Test fun manualMetadataOrderAbsentAndHybridMembersPreservedExactly() {val d=CollectionRules.fresh().apply{addProperty("nombre","Personalizado");addProperty("descripcion","Manual");addProperty("poster_url","https://mine.invalid/p.jpg");addProperty("backdrop_url","https://mine.invalid/b.jpg");addProperty("orden",7);addProperty("visible",false);addProperty("tmdb_collection_id",10);addProperty("future","keep")};val root=CollectionRules.save(CollectionRules.empty(),CollectionRules.members(d,listOf("absent","anime-manual","p1")),null);val p=SagaDetection.proposal(detail(),cat(1,2),root);val saved=CollectionRules.list(SagaDetection.approve(root,cat(1,2),listOf(p),setOf(10))).single();assertEquals(listOf("absent","anime-manual","p1","p0"),CollectionRules.ids(saved));val expected=CollectionRules.members(saved,emptyList());assertEquals(CollectionRules.members(d,emptyList()),expected)}
    @Test fun existingDuplicateTmdbCollectionsBlockAutomaticMerge() {val a=CollectionRules.fresh().apply{addProperty("nombre","A");addProperty("tmdb_collection_id",10)};val b=a.deepCopy().apply{addProperty("id","different")};val root=CollectionRules.save(CollectionRules.save(CollectionRules.empty(),a,null),b,null);val row=SagaDetection.proposal(detail(),cat(1),root);assertFalse(row.actionable);assertThrows(IllegalArgumentException::class.java){SagaDetection.approve(root,cat(1),listOf(row),setOf(10))}}
    @Test fun missingMoviesAreListedNotCreated() {val c=cat(1);val before=c.deepCopy();val p=SagaDetection.proposal(detail(),c,CollectionRules.empty());assertEquals(2,p.missing.size);val next=SagaDetection.approve(CollectionRules.empty(),c,listOf(p),setOf(10));assertEquals(listOf("p0"),CollectionRules.ids(CollectionRules.list(next).single()));assertEquals(before,c)}
    @Test fun approvingSubsetDoesNotCreateOthers() {val c=cat(1);val rows=listOf(SagaDetection.proposal(detail(10),c,CollectionRules.empty()),SagaDetection.proposal(detail(20),c,CollectionRules.empty()));val saved=CollectionRules.list(SagaDetection.approve(CollectionRules.empty(),c,rows,setOf(20)));assertEquals(listOf(20L),saved.map {it.number("tmdb_collection_id")})}
    @Test fun scanNeverMutatesCatalogOrCollections()=runTest {val c=cat(1,2);val root=CollectionRules.empty();val before=c.deepCopy();val old=root.deepCopy();engine(provider()).scan(c,root){_,_->};assertEquals(before,c);assertEquals(old,root)}
    @Test fun approvingDoesNotMutateTelegramOrDateOrMovieMetadata() {val c=cat(1,2);val before=c.deepCopy();val p=SagaDetection.proposal(detail(),c,CollectionRules.empty());SagaDetection.approve(CollectionRules.empty(),c,listOf(p),setOf(10));assertEquals(before,c)}
    @Test fun incompleteDetailsCountAsFailureAndNotAsComplete()=runTest {val p=Provider({10},{obj("""{"id":10,"name":"Missing parts"}""")});var status=SagaProgress();assertTrue(engine(p).scan(cat(1),CollectionRules.empty()){s,_->status=s}.isEmpty());assertEquals(1,status.failed);assertFalse(status.complete)}
    @Test fun mismatchedAndDuplicatePartsRejected() {for(d in listOf(detail(20),detail().apply{array("parts").add(array("parts")[0].deepCopy())},detail().apply{array("parts")[0].asJsonObject.remove("id")})) assertThrows(IllegalArgumentException::class.java){SagaDetection.validateDetail(d,10)}}
    @Test fun retryNetworkWithBoundedProgressiveWaitAndNoFalseComplete()=runTest {val p=provider {throw SagaRequestFailure()};val waits=mutableListOf<Long>();var status=SagaProgress();engine(p,wait={waits.add(it)}).scan(cat(1),CollectionRules.empty()){s,_->status=s};assertEquals(3,p.calls);assertTrue(1000L in waits && 2000L in waits);assertEquals(1,status.failed);assertFalse(status.complete)}
    @Test fun retry429HonorsRetryAfter()=runTest {var n=0;val p=provider {if(n++==0) throw SagaRequestFailure(429,5000);10};val waits=mutableListOf<Long>();engine(p,wait={waits.add(it)}).scan(cat(1),CollectionRules.empty()){_,_->};assertTrue(5000L in waits);assertEquals(2,p.calls)}
    @Test fun longRetryAfterNeverRetriedPrematurely()=runTest {val p=provider {throw SagaRequestFailure(429,120000)};val waits=mutableListOf<Long>();try {engine(p,wait={waits.add(it)}).scan(cat(1,2),CollectionRules.empty()){_,_->};fail()}catch(e:SagaRequestFailure){assertEquals(429,e.status)};assertEquals(1,p.calls);assertFalse(waits.any {it>=1000})}
    @Test fun authDeniedStopsBulkWithoutHundredsOfCalls()=runTest {val p=provider {throw SagaRequestFailure(401)};try{engine(p).scan(cat(1,2,3),CollectionRules.empty()){_,_->};fail()}catch(e:SagaRequestFailure){assertEquals(401,e.status)};assertEquals(1,p.calls)}
    @Test fun nonTransientFailureNotRetried()=runTest {val p=provider {throw SagaRequestFailure(404)};engine(p).scan(cat(1),CollectionRules.empty()){_,_->};assertEquals(1,p.calls)}
    @Test fun cachePersistsMembershipAndDetailsAcrossRestart()=runTest {val store=Store();val p=provider();engine(p,store).scan(cat(1,2),CollectionRules.empty()){_,_->};val again=provider {error("must use cache")};engine(again,store).scan(cat(1,2),CollectionRules.empty()){_,_->};assertEquals(0,again.calls);assertEquals(0,again.details)}
    @Test fun nullMembershipAlsoCached()=runTest {val s=Store();engine(provider {null},s).scan(cat(1),CollectionRules.empty()){_,_->};val p=provider();engine(p,s).scan(cat(1),CollectionRules.empty()){_,_->};assertEquals(0,p.calls)}
    @Test fun cacheExpiresAndCanBeExplicitlyCleared() {val s=Store();var now=1000000000L;val cache=SagaCache(s){now};cache.movie(1,10);assertTrue(cache.movie(1).first);now+=8L*24*60*60*1000;assertFalse(cache.movie(1).first);cache.movie(1,null);cache.clear();assertFalse(cache.movie(1).first)}
    @Test fun failedQueriesNotCachedAndResumeRetriesOnlyMissing()=runTest {val s=Store();var n=0;val p=provider {if(it==2L) throw SagaRequestFailure(404);10};engine(p,s).scan(cat(1,2),CollectionRules.empty()){_,_->};val q=provider {n++;assertEquals(2L,it);10};engine(q,s).scan(cat(1,2),CollectionRules.empty()){_,_->};assertEquals(1,n)}
    @Test fun cancellationLeavesCompletedCacheAndNoCollectionsSaved()=runTest {val s=Store();val c=cat(1,2,3);val root=CollectionRules.empty();var count=0;try{engine(provider(),s).scan(c,root){status,_->if(status.analyzed==1 && count++==0) throw CancellationException()};fail()}catch(_:CancellationException){};assertTrue(SagaCache(s).movie(1).first);assertFalse(SagaCache(s).movie(2).first);assertTrue(CollectionRules.list(root).isEmpty())}
    @Test fun progressIncludesDuplicatesMissingFailuresAndPending()=runTest {val c=cat(1,1,2,3);c.array("items")[3].asJsonObject.remove("tmdb_id");var last=SagaProgress();engine(provider {if(it==2L) throw SagaRequestFailure(404);10}).scan(c,CollectionRules.empty()){s,_->last=s};assertEquals(4,last.total);assertEquals(3,last.analyzed);assertEquals(0,last.pending);assertEquals(1,last.failed);assertEquals(1,last.missing)}
    @Test fun atomicBatchHasOneBackupAndRestarts() {val store=Store();val r=CollectionRepository(store);val c=cat(1);val root=r.data();val rows=listOf(SagaDetection.proposal(detail(10),c,root),SagaDetection.proposal(detail(20),c,root));r.replaceApproved(SagaDetection.approve(root,c,rows,setOf(10,20)));assertEquals(2,CollectionRules.list(CollectionRepository(store).data()).size);r.undo();assertTrue(CollectionRules.list(r.data()).isEmpty())}
    @Test fun batchWriteFailureKeepsOldStateAndBackup() {val store=Store();val r=CollectionRepository(store);val before=r.data();val next=CollectionRules.save(before,CollectionRules.fresh().apply{addProperty("nombre","Test")},null);store.fail=true;assertThrows(IllegalStateException::class.java){r.replaceApproved(next)};assertEquals(before,r.data())}
    @Test fun saved018BackupRestoresWithoutMigrationAndKeepsId() {val d=CollectionRules.members(CollectionRules.fresh().apply{addProperty("nombre","Depredador");addProperty("tmdb_collection_id",10);addProperty("origen","tmdb")},listOf("p0","absent"));val raw=CollectionRules.save(CollectionRules.empty(),d,null).toString();val s=Store();val r=CollectionRepository(s);r.restore(raw);assertEquals(d,CollectionRules.list(CollectionRepository(s).data()).single())}
    @Test fun activeDraftPreventsBatchOverwrite() {val r=CollectionRepository(Store());r.stage(CollectionRules.fresh(),null);assertThrows(IllegalStateException::class.java){r.replaceApproved(CollectionRules.empty())};assertNotNull(r.draft())}
    @Test fun sourceDoesNotOfferTitleSimilarityDuringBulk() {val c=cat(1);c.array("items")[0].asJsonObject.remove("tmdb_id");c.array("items")[0].asJsonObject.addProperty("titulo","Uno");c.array("items")[0].asJsonObject.addProperty("anio","2000");val d=detail();d.array("parts")[0].asJsonObject.addProperty("release_date","2000-01-01");assertTrue(SagaDetection.proposal(d,c,CollectionRules.empty()).matches.all {it.possible.isEmpty()})}
    @Test fun rateLimitCooldownSurvivesRestartAndCannotBeBypassedByClear()=runTest {val s=Store();val cache=SagaCache(s);cache.cooldown(120000);cache.clear();val p=provider();try {engine(p,s).scan(cat(1),CollectionRules.empty()){_,_->};fail()}catch(e:SagaRequestFailure){assertEquals(429,e.status)};assertEquals(0,p.calls)}
    @Test fun catalogChangeBeforeApprovalCannotAddRemovedMovie() {val c=cat(1);val p=SagaDetection.proposal(detail(),c,CollectionRules.empty());assertThrows(IllegalArgumentException::class.java){SagaDetection.approve(CollectionRules.empty(),cat(),listOf(p),setOf(10))}}
    @Test fun hundredsOfMoviesUseOneRequestAtATimeAndOneDetailPerSaga()=runTest {val c=cat(*(1..400).toList().toIntArray());var active=0;var peak=0;val p=Provider({active++;peak=maxOf(peak,active);active--;10},{detail(it)});engine(p).scan(c,CollectionRules.empty()){_,_->};assertEquals(400,p.calls);assertEquals(1,p.details);assertEquals(1,peak)}
    @Test fun retryAfterParsesSecondsDateAndInvalidSafely() {assertEquals(3000L,SagaDetection.retryAfter("3"));assertEquals(5000L,SagaDetection.retryAfter("Wed, 21 Oct 2015 07:28:00 GMT",Instant.parse("2015-10-21T07:27:55Z")));assertNull(SagaDetection.retryAfter("oops"));assertNull(SagaDetection.retryAfter("-1"))}
}
